import json
from pathlib import Path
A=[]
def add(i,s,q,m,**kw):
    if kw.get('counterparty_evidence')=='named': kw['counterparty']='CoreWeave Compute Acquisition Co., IV, LLC'
    A.append(dict(index=i,classification='material',summary=s,rows=[dict(quote=q,model_quantity=m,stage='recognized',issuer_treatment=s,**kw)]))
add(371,'MSD : NAV 23,87→23,71 dollars en 2025 ; NII 2,43 contre distributions 2,54, dont 0,09 retour de capital. Ne pas assimiler les distributions au seul revenu ni au cash effectivement sorti compte tenu du DRP. Net assets 3,278352 Md$, engagements investisseurs 3,539354 Md$ et ratio contribué 83,35 % sont des grandeurs distinctes. Couverture des actifs 200,8 % contre minimum 150 %, dette moyenne 2,776963 Md$ distincte du solde final.','Distributions from return of capital','msd_distribution_return_of_capital_and_coverage')
add(372,'MSD : BDC privée, non diversifiée, RIC/ASC946. SPV I, SPV II et CLO I sont consolidés comme véhicules de financement ; les sociétés opérationnelles du portefeuille ne le sont généralement pas. La levée initiale a acquis un portefeuille auprès de fonds gérés : transfert secondaire affilié, pas preuve de cash primaire nouveau chez les emprunteurs. Réorganisation BDT & MSD de 2025 sans changement de services ou frais. Décision du 4 mars 2025 de rester privée indéfiniment ; les 250 actions préférentielles à 12 % ont toutes été remboursées le 15 décembre 2025.','The proceeds received at the Initial Closing Date were used to acquire the initial portfolio','msd_secondary_initial_portfolio_and_consolidation')
add(373,'MSD : engagements non financés 679,658 M$ à fin 2025 et FV négative 6,054 M$, contre 574,819 M$/−4,151 M$ en 2024. CoreWeave Compute Acquisition Co IV : 10,168 M$ non tirés, expiration 31 mars 2026, FV +8 k$, contre 26,094 M$ fin 2024. La baisse du disponible ne prouve ni paiement ni remboursement ; expiration de l’engagement distincte de la maturité du prêt financé. Montant global non attribuable entièrement à l’IA. Le nominal hors bilan n’exclut pas une FV comptabilisée ; engagements pouvant expirer sans tirage.','CoreWeave Compute Acquisition Co., IV, LLC','msd_coreweave_undrawn_commitment',counterparty_evidence='named')
add(374,'MSD : portefeuille et cash FV 6,519712 Md$ à fin 2025, dont L3 5,643366 Md$ (86,56 % du total avec cash). Le portefeuille seul vaut 6,391054 Md$. Achats L3 2,527615 Md$ incluent PIK ; ils ne sont pas tous du cash primaire. La valorisation par rendement suppose notamment récupération intégrale du principal à maturité attendue ; inputs non observables, prix indicatifs non engageants et reclassements de hiérarchie ne prouvent pas une transaction. FV des notes 1,263035 Md$ distincte du principal 1,25 Md$, excluant autres emprunts.','Purchase of investments (including PIK)','msd_level3_non_cash_purchases_and_debt_fair_value',judgment_sensitive=True)
add(375,'MSD : engagements de capital ~3,5 Md$ dont 589,4 M$ non appelés ; levées effectivement appelées cumulées 2,949988 Md$, dont 800 M$ aux trois dates de 2025. Distributions 2025 déclarées 287,867 M$/2,54 par action ; DRP 2025 103,060 M$ calculés à partir des quatre lignes, déjà dans les distributions, et non levée primaire indépendante. DRP cumulé depuis 2022 358,521 M$, les actions réinvesties ne diminuent pas les engagements non appelés. Préférentielles toutes remboursées en décembre.','Shares issued under the DRP will not reduce outstanding Capital Commitments.','msd_capital_drawdowns_and_reinvested_distributions')
add(376,'MSD : portefeuille FV 6,391054 Md$, coût 6,389065 Md$, 99,28 % first lien et 194,95 % des actifs nets à fin 2025. Une position non-accrual, identité non donnée dans cette note ; aucune attribution à CoreWeave. Dette performante 99,2 % à taux variable. La catégorie High Tech 8,19 % ne mesure pas l’IA : pas de requalification sectorielle automatique. Diversification du portefeuille ne supprime pas le levier ni la sensibilité aux taux.','one investment in the portfolio was on non-accrual status.','msd_portfolio_leverage_and_unidentified_nonaccrual')
Path(__file__).with_suffix('.json').write_text(json.dumps(A,ensure_ascii=False,indent=2)+'\n')
M=json.loads(Path('work/continuation398/scope.json').read_text())['rows']
for a in A:
    t=json.loads(Path(M[a['index']]['path']).read_text())['text']
    for r in a['rows']: assert r['quote'] in t,(a['index'],r['quote'])
